mapper.select:
select id, stock_date, mix_area, glue, stock_num, remark, del_flag, create_by, create_time, update_by, update_time, bar_code,valid_time, stock_weight from t_bhg_glue_stock where del_flag = '0' and stock_date = #{stockDate} and mix_area = #{mixArea} and INSTR(glue, #{glue}) > 0
order by stock_date desc,valid_time asc
order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber} row_numbers, #{bhgGlueStock.stockDate,jdbcType=TIMESTAMP} stock_date, #{bhgGlueStock.barCode,jdbcType= VARCHAR} bar_code
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_bhg_glue_stock m inner join temp_table t on m.stock_date = t.stock_date and m.bar_code = t.bar_code and m.del_flag ='0'

