select #{bhgGlueStock.stockDate,jdbcType=TIMESTAMP} stock_date, #{bhgGlueStock.mixArea,jdbcType= VARCHAR} mix_area, #{bhgGlueStock.glue,jdbcType= VARCHAR} glue, #{bhgGlueStock.stockNum,jdbcType=DOUBLE} stock_num, #{bhgGlueStock.remark,jdbcType= VARCHAR} remark, #{bhgGlueStock.delFlag,jdbcType= VARCHAR} del_flag, #{bhgGlueStock.createBy,jdbcType= VARCHAR} create_by, #{bhgGlueStock.createTime,jdbcType=TIMESTAMP} create_time, #{bhgGlueStock.updateBy,jdbcType= VARCHAR} update_by, #{bhgGlueStock.updateTime,jdbcType=TIMESTAMP} update_time, #{bhgGlueStock.barCode,jdbcType=VARCHAR} bar_code,#{bhgGlueStock.validTime, jdbcType=TIMESTAMP} valid_time, #{bhgGlueStock.stockWeight,jdbcType=DOUBLE} stock_weight
) x
